"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73425"],{66551(e){e.exports=JSON.parse('{"id":"FIN-301","slug":"price-elasticity-of-demand","term":"Price Elasticity of Demand","also_known_as":[],"difficulty":"Intermediate","definition":"Price elasticity of demand measures how strongly the quantity of a good that people buy responds to a change in its price.","explanation":["Elasticity compares the percentage change in quantity demanded with the percentage change in price. If a small price rise causes a large fall in purchases, demand is elastic. If purchases barely change, demand is inelastic.","Suppose a caf\xe9 raises the price of coffee from 4.00 to 4.40, about a 10% increase, and weekly sales fall from 1,000 to 920 cups, about an 8% decrease. The elasticity is roughly \u22120.8. Because the figure is less than 1 in absolute size, demand is inelastic: sales fell, but proportionally less than the price rose. The caf\xe9\'s revenue actually rises, from 4,000 to 4,048 a week.","Demand tends to be more elastic when close substitutes exist, when the product takes up a large share of a budget, when it is a luxury and over longer periods, as people have time to adjust. Essential medicines and fuel in the short term tend to have inelastic demand. A particular brand of soft drink tends to have elastic demand.","Elasticity helps businesses set prices and helps governments predict how taxes will affect consumption and revenue."],"note":"","total":1500,"prev":{"slug":"price-discrimination","term":"Price Discrimination"},"next":{"slug":"price-elasticity-of-supply","term":"Price Elasticity of Supply"}}')}}]);